function NumericInput({value,min,max,step=1,label,onChange}:{value:number,min:number,max:number,step?:number,label:string,onChange:(value:number)=>void}){
 const language=useLanguage();const digits=step<1?2:0;const [draft,setDraft]=useState(()=>numberText(value,digits));
 useEffect(()=>setDraft(numberText(value,digits)),[value,digits,language]);
 function commit(){const parsed=parseLocalizedNumber(draft);if(!draft.trim()||!Number.isFinite(parsed)){setDraft(numberText(value,digits));return}const clamped=Math.max(min,Math.min(max,parsed));const snapped=Math.max(min,Math.min(max,Number((min+Math.round((clamped-min)/step)*step).toFixed(6))));onChange(snapped);setDraft(numberText(snapped,digits))}
 return <input className="numeric-input" type="text" inputMode={step<1?'decimal':'numeric'} role="spinbutton" aria-label={t(label)} aria-valuemin={min} aria-valuemax={max} aria-valuenow={value} value={draft} onChange={e=>setDraft(e.target.value)} onBlur={commit} onKeyDown={e=>{if(e.key==='Enter'){e.currentTarget.blur()}if(e.key==='Escape'){setDraft(numberText(value,digits))}if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();const next=Math.max(min,Math.min(max,Number((value+(e.key==='ArrowUp'?step:-step)).toFixed(6))));onChange(next)}}}/>;
}
