async function cropPhoto(rect:CropRect){if(busy)return;setBusy(true);const settings={...o},photoId=selectedPhotoId;let objectUrl:string|undefined;try{const canvas=document.createElement('canvas');let width=source.width,height=source.height,drawable:CanvasImageSource;if(fullFile.current){const image=new Image();objectUrl=URL.createObjectURL(fullFile.current);await new Promise<void>((resolve,reject)=>{image.onload=()=>resolve();image.onerror=reject;image.src=objectUrl!});width=image.naturalWidth;height=image.naturalHeight;drawable=image}else{const originalCanvas=document.createElement('canvas');originalCanvas.width=width;originalCanvas.height=height;originalCanvas.getContext('2d')!.putImageData(source,0,0);drawable=originalCanvas}const x=Math.min(width-1,Math.floor(rect.x*width)),y=Math.min(height-1,Math.floor(rect.y*height)),w=Math.max(1,Math.min(width-x,Math.round(rect.width*width))),h=Math.max(1,Math.min(height-y,Math.round(rect.height*height)));canvas.width=w;canvas.height=h;canvas.getContext('2d')!.drawImage(drawable,x,y,w,h,0,0,w,h);const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error('crop')),'image/png'));const cropped=new File([blob],'kirpilmis-fotograf.png',{type:'image/png'});const loaded=await load(cropped);if(!loaded)throw new Error('crop load');if(photoId!==null){const preview=queueUrl(cropped);const previous=photoQueue.find(photo=>photo.id===photoId);releaseQueueUrl(previous?.preview);releaseQueueUrl(previous?.result);setPhotoQueue(old=>old.map(photo=>photo.id===photoId?{...photo,file:cropped,preview,result:undefined,settings,state:'waiting',error:undefined}:photo));setSelectedPhotoId(photoId)}setO(settings);setCropping(false);setMessage(`Fotoğraf kırpıldı · ${numberText(w)} × ${numberText(h)} piksel`)}catch{setUploadError('Fotoğraf kırpılamadı. Daha küçük bir fotoğrafla tekrar dene.')}finally{if(objectUrl)URL.revokeObjectURL(objectUrl);setBusy(false)}}
async function load(file?:File){if(!file)return false;try{file=await unlockImageFile(file)||file}catch(e){setUploadError(e instanceof Error?e.message:ui.text077);return false}setSelectedPhotoId(null);if(!file.type.startsWith('image/')){setUploadError(ui.text076);return false}setUploadError('');try{audioContext()}catch{}setBusy(true);const u=URL.createObjectURL(file);try{const img=new Image();await new Promise<void>((resolve,reject)=>{img.onload=()=>resolve();img.onerror=reject;img.src=u});const scale=Math.min(1,1400/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));const ctx=c.getContext('2d')!;ctx.drawImage(img,0,0,c.width,c.height);fullFile.current=file;setSource(ctx.getImageData(0,0,c.width,c.height));setO({...defaults});setMessage(`${file.name} yüklendi · ${c.width} × ${c.height}`);return true}catch{setUploadError(ui.text077);return false}finally{URL.revokeObjectURL(u);setBusy(false)}}
function auto(inputImage:ImageData=source){const report=analyzeAutomatic(inputImage);setAutoReport(report);setO(report.settings);setMessage(ui.text078)}

function aiCommand(command:AiCommand){
 const {name,arguments:args}=command;
 if(name==='pollmek_status')return {width:source.width,height:source.height,settings:o,appliedSettings,processing,busy:busy||queueRunning,error:processingError||null};
 if(name==='pollmek_histogram'){if(processing||busy||queueRunning)throw new Error('Image is processing; wait and check status.');return {before:stats(processedSource),after:stats(output),width:output.width,height:output.height}}
 if(busy||queueRunning||processing)throw new Error('Studio is busy; wait and check status before editing.');
 let next:Settings;
 if(name==='pollmek_apply')next=aiSettingsPatch(args.settings,o);
 else if(name==='pollmek_auto'){const report=analyzeAutomatic(source);setAutoReport(report);next=report.settings}
 else if(name==='pollmek_reset')next={...defaults};
 else throw new Error('Unknown command');
 if(name!=='pollmek_auto')setAutoReport(null);
 setO(next);setMessage(t('AI ayarları uygulandı.'));studio();
 return {accepted:true,processing:'queued',settings:next,instruction:'Call pollmek_status to confirm processing has finished.'};
}

